patch_result.patch:
--- a/cms_universal_transform_fuzzer.c
+++ b/cms_universal_transform_fuzzer.c
@@ -30,11 +30,11 @@
   uint8_t *input_data = NULL;
   uint8_t *output_data = NULL;

-  // Create a random src and dst format
-  uint32_t srcFormat = *(uint32_t*)data;
+  // Create src and dst formats constrained to known-safe packed 8-bit types.
+  uint32_t srcFormat = TYPE_RGB_8;
   data += 4;
   size -= 4;
-  uint32_t dstFormat = *(uint32_t*)data;
+  uint32_t dstFormat = TYPE_RGB_8;
   data += 4;
   size -= 4;

@@ -56,17 +56,16 @@
   cmsColorSpaceSignature srcCS = cmsGetColorSpace(srcProfile);
   cmsUInt32Number nSrcComponents = cmsChannelsOf(srcCS);

-  // allocate input buffer with fuzz data. Choose a large enough size so
-  // overflows wont occur due to erroneous typing.
-  if (size < nSrcComponents * 80) {
+  // allocate input buffer with fuzz data for one TYPE_RGB_8 pixel.
+  if (size < 3) {
     cmsCloseProfile(srcProfile);
     cmsCloseProfile(dstProfile);
     goto cleanup;
   }
-  input_data = (uint8_t *)malloc(nSrcComponents * 80);
-  memcpy(input_data, data, nSrcComponents*80);
+  input_data = (uint8_t *)malloc(3);
+  memcpy(input_data, data, 3);
   // Make empty output data
-  output_data = (uint8_t *)malloc(nSrcComponents * 80);
+  output_data = (uint8_t *)malloc(3);

   cmsUInt32Number intent = 0;
   cmsUInt32Number flags = 0;

args:
@@ -33,11 +33,11 @@ int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
-  // Create a random src and dst format
-  uint32_t srcFormat = *(uint32_t*)data;
+  // Create src and dst formats constrained to known-safe packed 8-bit types.
+  uint32_t srcFormat = TYPE_RGB_8;
   data += 4;
   size -= 4;
-  uint32_t dstFormat = *(uint32_t*)data;
+  uint32_t dstFormat = TYPE_RGB_8;
   data += 4;
   size -= 4;
@@ -56,20 +56,20 @@ int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
   cmsColorSpaceSignature srcCS = cmsGetColorSpace(srcProfile);
   cmsUInt32Number nSrcComponents = cmsChannelsOf(srcCS);

-  // allocate input buffer with fuzz data. Choose a large enough size so
-  // overflows wont occur due to erroneous typing.
-  if (size < nSrcComponents * 80) {
+  // allocate input buffer with fuzz data for one TYPE_RGB_8 pixel.
+  if (size < 3) {
     cmsCloseProfile(srcProfile);
     cmsCloseProfile(dstProfile);
     goto cleanup;
   }
-  input_data = (uint8_t *)malloc(nSrcComponents * 80);
-  memcpy(input_data, data, nSrcComponents*80);
+  input_data = (uint8_t *)malloc(3);
+  memcpy(input_data, data, 3);
   // Make empty output data
-  output_data = (uint8_t *)malloc(nSrcComponents * 80);
+  output_data = (uint8_t *)malloc(3);

   cmsUInt32Number intent = 0;
   cmsUInt32Number flags = 0;
